const range=(a,b)=>Array.from({length:b-a+1},(_,i)=>a+i);
export function reviewedRailViews(id){
 const r1=id==='voron_v02r1_120',key=n=>(r1?'v02r1_':'v02_')+String(n).padStart(5,'0');
 const yBeam=[0,10],zBeam=[13,14],yPairs=r1?[56,57,79,80]:[54,55,77,78],zPairs=r1?[102,103,125,126]:[100,101,123,124];
 const yNut=r1?[58,81,...range(69,78),...range(92,101)]:[56,79,...range(67,76),...range(90,99)],zNut=r1?[104,127,...range(115,124),...range(138,147)]:[102,125,...range(113,122),...range(136,145)];
 const yScrews=r1?[...range(59,68),...range(82,91)]:[...range(57,66),...range(80,89)],zScrews=r1?[...range(105,114),...range(128,137)]:[...range(103,112),...range(126,135)];
 const yStops=r1?[148,149,34,35,46,47]:[146,147,34,35,44,45],zStops=r1?[151,152,37,38,54,55]:[149,150,37,38,52,53],zLower=r1?[150,36,53]:[148,36,51];
 const y=[...yBeam,...yPairs,...yNut,...yScrews],z=[...zBeam,...zPairs,...zNut,...zScrews],rows=[];
 const row=(id,page,add,refs)=>rows.push({id,page,add:add.map(key),refs:refs.map(key)});
 row('y-rail-lubrication',19,yPairs,yPairs);row('y-rails',20,yBeam,[...yBeam,...yNut]);row('y-rail-mounts',21,yScrews,y);row('y-rail-position',22,[],y);row('y-rail-retention',22,[],y);row('y-rail-stops',23,yStops,[...y,...yStops]);
 row('z-rails',24,zBeam,[...zBeam,...zNut]);row('z-rail-mounts',25,[...zPairs,...zScrews],z);row('z-rail-position',26,[],z);row('z-rail-stops-upper',26,zStops,[...z,...zStops]);
 return {key,rows,lower:zLower.map(key),screws:[yScrews.map(key),zScrews.map(key)]};
}
export function attachRailFixtureMetadata(parts,id){const src=originals[id];return parts.map(p=>({...p,...structuredClone(src.parts[p.key]||{})}));}
export function auditRailOwnership({id,spec,manifest}){
 const review=reviewedRailViews(id),seen=new Set(),parts=new Map(manifest.parts.map(p=>[p.key,p]));
 for(const s of spec.stages)for(const key of s.part_keys){assert(!seen.has(key),'Original source duplicated '+key);seen.add(key)}assert.equal(seen.size,spec.parts);
 for(const row of review.rows){const s=spec.stages.find(s=>s.id===row.id);assert(s);assert.equal(s.page_start,row.page);assert.equal(s.page_end,row.page);assert.deepEqual(s.part_keys,row.add);assert.deepEqual(new Set(s.operation_part_keys),new Set(row.refs));}
 const owner=k=>spec.stages.find(s=>s.part_keys.includes(k)).id;assert.equal(owner(review.key(11)),'z-crossmembers','Top B beam belongs to the following frame section');assert.deepEqual(spec.stages.find(s=>s.id==='z-stops').part_keys,review.lower,'Only remaining lower Z stop on page35');
 for(const[k,v]of Object.entries(originals[id].parts)){const p=parts.get(k);for(const f of ['name','solid_count','appearance_role','source'])assert.deepEqual(p?.[f],v[f],'Exact source occurrence '+k+'/'+f);}
 for(const keys of review.screws){assert.equal(keys.length,20);for(const k of keys)assert.match(parts.get(k).name,/M2x6/);}
 for(const name of ['y-rail-mounts','z-rail-mounts']){const note=spec.stages.find(s=>s.id===name).note;assert.match(note,/five/);assert.match(note,/ten/);assert.match(note,/page 18/);}
 return {operations:review.rows.length,originalSourceParts:Object.keys(originals[id].parts).length,originalScrews:40,allOriginalKeysOnce:true,upperStopsPage26:true,lowerStopPage35:true,topBInFollowingFrameSection:true,fullPopulationOptionRetained:true,physicalFitQualified:false};
}
export function applyReviewedRailMask({id,index,spec,keys,result}){
 const row=reviewedRailViews(id).rows.find(r=>r.id===spec.stages[index].id);if(!row)return null;
 const before=new Set(keys),allow=new Set(row.refs);for(const k of keys)if(!allow.has(k))keys.delete(k);
 assert.equal(result.subassembly,true);assert.deepEqual(new Set(result.operation_part_keys),allow);assert.deepEqual(new Set(result.stored_keys),new Set(spec.stages.slice(0,index+1).flatMap(s=>s.part_keys).filter(k=>!allow.has(k))));
 assert.deepEqual(keys,allow);assert.deepEqual(result.camera_direction,[.65,.45,1]);assert.equal(result.camera_distance_floor,.05);return {id:row.id,visible:keys.size,refs:allow.size};
}

export function auditActualRailDisplay({id,module,adapter,manifest,spec,receipts,companions,scene,installed,geometryPins,createAssemblyStageEmphasis,assemblySourceMaterial,powerReferences}){
 const original=new Map(),colors=new Map();scene.updateMatrixWorld(true);scene.traverse(n=>{original.set(n,{visible:n.visible,position:n.position.toArray(),quaternion:n.quaternion.toArray(),scale:n.scale.toArray(),world:n.matrixWorld.toArray(),material:n.material});for(const m of n.material?(Array.isArray(n.material)?n.material:[n.material]):[])if(!colors.has(m))colors.set(m,m.color?.clone())});const geometry=geometryPins(scene),review=reviewedRailViews(id);
 const c=module.createV0AssemblyStages({nodes:adapter.nodes,manifest,machine:spec,receipts,companions,manualPreparation:true,powerReferences}),display=createAssemblyStageEmphasis(),visits=[];
 const checkFrames=()=>{scene.updateMatrixWorld(true);for(const[n,r]of original){assert.deepEqual(n.position.toArray(),r.position);assert.deepEqual(n.quaternion.toArray(),r.quaternion);assert.deepEqual(n.scale.toArray(),r.scale);assert.deepEqual(n.matrixWorld.toArray(),r.world)}};
 const visit=(name,gray)=>{const i=spec.stages.findIndex(s=>s.id===name);c.setStage(i);const keys=spec.stages[i].operation_part_keys||spec.stages[i].part_keys;display.update({parts:c.getDisplayedParts(),currentKeys:keys,enabled:gray});let source=0,dim=0;
  for(const p of c.getDisplayedParts())for(const root of p.nodes)root.traverse(n=>{if(!n.isMesh)return;if(keys.includes(p.key)){assert.equal(n.material,assemblySourceMaterial(n));source++}else if(gray){assert.notEqual(n.material,assemblySourceMaterial(n));dim++}});assert(source>0);checkFrames();display.clear();for(const[n,r]of original)assert.equal(n.material,r.material);return{id:name,gray,currentSourceMeshes:source,dimmedEarlierMeshes:dim};};
 for(const r of review.rows)visits.push(visit(r.id,true));for(const r of [...review.rows].reverse())visit(r.id,false);
 const frame=visit('z-crossmembers',true);assert(frame.dimmedEarlierMeshes>0);visit('z-stops',true);
 const from=spec.stages.findIndex(s=>s.id==='y-rails'),to=spec.stages.findIndex(s=>s.id==='y-rail-mounts');c.setStage(from);const before=c.getVisibleKeys(),n=adapter.nodes.get(review.screws[0][0]),d=Object.getOwnPropertyDescriptor(n,'visible');Object.defineProperty(n,'visible',{...d,writable:false});try{assert.throws(()=>c.setStage(to),/Native visibility/)}finally{Object.defineProperty(n,'visible',d)}assert.equal(c.current().id,'y-rails');assert.deepEqual(c.getVisibleKeys(),before);checkFrames();c.leave();
 for(const palette of [{base:'#173c68',accent:'#edd13e'},{base:'#edd13e',accent:'#173c68'},{base:'#a4d2bc',accent:'#602843'}]){adapter.setPalette(palette);installed.setPalette(palette);visit('y-rail-stops',true);for(const k of review.screws.flat()){const root=adapter.nodes.get(k);root.traverse(n=>{if(!n.isMesh)return;for(const m of Array.isArray(n.material)?n.material:[n.material])if(colors.get(m))assert.equal(m.color.getHex(),colors.get(m).getHex(),'Original screw hardware color retained')})}c.leave();}
 installed.setPalette({});for(const[m,color]of colors)if(color)m.color.copy(color);checkFrames();for(const[n,r]of original){assert.equal(n.material,r.material);assert.equal(n.visible,r.visible)}assert.deepEqual(geometryPins(scene),geometry);display.dispose();
 return{visits,reverseVisits:10,separatePalettes:3,visibilityRollback:1,fullGeometryContentRetained:true,originalFramesMaterialsVisibilityRestored:true,physicalFitQualified:false,scope:'Ten original rail operation views, changed frame/lower stop references, optional gray, three separate palette visits and failed visibility rollback. No new motion, insertion, torque, native contact or whole physical fit certification.'};
}
